<?php

declare(strict_types=1);

namespace App\Content\Builder;

/**
 * Where a school's lesson is (A7.2): a draft, being generated by AI (A7.3),
 * waiting for the instructor's line-by-line review (A8.1), or approved.
 * Learners see a school's lessons only once approved; REOS library lessons
 * have no review status.
 */
enum LessonReview: string
{
    case Draft = 'draft';
    case Generating = 'generating';
    case InReview = 'in_review';
    case Approved = 'approved';
}
